begin;create extension if not exists pgtap with schema extensions;set local search_path=public,extensions;select no_plan();
create temp table cr_fx(k text primary key,id uuid,v jsonb);grant all on cr_fx to authenticated,service_role;
insert into cr_fx(k,id)select k,gen_random_uuid()from unnest(array['actor','other','sid','other_sid','job','attempt','review','canceled','attemptcancel','policycancel','link','stalejob','staleattempt','heldjob','heldattempt','missingreview','policyaction','v2job','v2attempt','v3job','v3attempt'])k;
create function pg_temp.cr_id(key text)returns uuid language sql as $$select id from cr_fx where k=$1$$;
insert into auth.users(id,email,raw_user_meta_data)select id,'synthetic-recap-'||id||'@example.test','{}'from cr_fx where k in('actor','other');update profiles set is_active=true,full_name='Synthetic recap staff'where id in(pg_temp.cr_id('actor'),pg_temp.cr_id('other'));insert into user_roles(user_id,role)values(pg_temp.cr_id('actor'),'ADMIN'),(pg_temp.cr_id('other'),'STAFF')on conflict do nothing;
insert into auth.sessions(id,user_id,created_at,updated_at)values(pg_temp.cr_id('sid'),pg_temp.cr_id('actor'),now(),now()),(pg_temp.cr_id('other_sid'),pg_temp.cr_id('other'),now(),now());
select ok(relrowsecurity and not has_table_privilege('authenticated',oid,'SELECT')and not has_table_privilege('service_role',oid,'SELECT')and not has_table_privilege('anon',oid,'SELECT'),relname||' private')from pg_class where relnamespace='public'::regnamespace and relname like'clinical_recap_%'and relkind='r';
select is((select count(*)::integer from pg_constraint where contype='f'and conrelid in(select oid from pg_class where relnamespace='public'::regnamespace and relname like'clinical_recap_%')and confrelid in('pets'::regclass,'clinical_encounters'::regclass,'clinical_addenda'::regclass,'patient_problems'::regclass)),0,'No canonical source FK lock acquisitions');
select ok(has_function_privilege('authenticated',oid,'EXECUTE')and not has_function_privilege('anon',oid,'EXECUTE')and not has_function_privilege('service_role',oid,'EXECUTE'),proname||' staff scope')from pg_proc where pronamespace='public'::regnamespace and proname in('read_clinical_recap_policy','recover_clinical_recap_policy','cancel_clinical_recap_policy','save_clinical_recap_policy','preview_clinical_recap','read_clinical_recap_job','read_clinical_recap_citation','reserve_clinical_recap','cancel_clinical_recap_reservation','list_clinical_recap_sources','list_clinical_recaps','claim_clinical_recap','cancel_clinical_recap_attempt','recover_clinical_recap_review','cancel_clinical_recap_review','save_clinical_recap_review');
select ok(has_function_privilege('service_role',oid,'EXECUTE')and not has_function_privilege('authenticated',oid,'EXECUTE')and not has_function_privilege('anon',oid,'EXECUTE'),proname||' worker scope')from pg_proc where pronamespace='public'::regnamespace and proname in('dispatch_clinical_recap','fail_clinical_recap','finish_clinical_recap');
select ok(not has_function_privilege('authenticated',oid,'EXECUTE')and not has_function_privilege('anon',oid,'EXECUTE')and not has_function_privilege('service_role',oid,'EXECUTE'),proname||' private helper')from pg_proc where pronamespace='public'::regnamespace and proname like'clinical_recap_%';
select is((select count(*)::integer from pg_trigger where tgname='zzz_clinical_recap_epoch'),5,'Five source writer families participate');
select set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',pg_temp.cr_id('actor'),'session_id',pg_temp.cr_id('sid'))::text,true);set local role authenticated;
insert into cr_fx(k,id)select'client',id from save_client(auth.uid(),null,null,'Synthetic','Recap','+13035555582','synthetic-recap@example.test','EMAIL',null,null);
insert into cr_fx(k,id)select'pet',id from save_patient(null,pg_temp.cr_id('client'),null,'Synthetic Recap','Dog','Mixed',null,'unknown','','unknown','unknown','',null,null);
insert into cr_fx(k,id)select'other_pet',id from save_patient(null,pg_temp.cr_id('client'),null,'Other Recap','Dog','Mixed',null,'unknown','','unknown','unknown','',null,null);
insert into cr_fx(k,id)select'enc',id from save_clinical_encounter(null,pg_temp.cr_id('pet'),null,now(),'clinic','Test','Fictional cough.','Not examined.','Possible historical cough.','CBC declined.');
insert into cr_fx(k,id)select'draft',id from save_clinical_encounter(null,pg_temp.cr_id('pet'),null,now(),'clinic','Test','Unsigned source.','','','');
select sign_clinical_encounter(pg_temp.cr_id('enc'),1);
insert into cr_fx(k,id)select'add',id from add_clinical_addendum(pg_temp.cr_id('enc'),'Historical clarification, not a new exam.');
insert into cr_fx(k,id)select'problem',id from save_patient_problem(null,pg_temp.cr_id('pet'),null,'Historical cough','Owner reported',null,'resolved','high');
insert into cr_fx(k,v)select'selection',jsonb_build_object('encounter_ids',jsonb_build_array(pg_temp.cr_id('enc')),'include_native_problems',true,'visit_from',null,'visit_to',null);
insert into cr_fx(k,v)select'preview',preview_clinical_recap(auth.uid(),pg_temp.cr_id('pet'),(select v from cr_fx where k='selection'));
select is((select v#>>'{source_set,budgets,source_units}'from cr_fx where k='preview'),'3','Signed SOAP, complete addendum and native problem captured');
select is((select v#>>'{source_set,sources,0,kind}'from cr_fx where k='preview'),'addendum','Sources use canonical kind/ID order');
select is((select v#>>'{source_set,sources,0,version}'from cr_fx where k='preview'),null,'Addendum version is explicitly null');
select is((select(v#>>'{source_set,budgets,source_bytes}')::integer from cr_fx where k='preview'),(select octet_length(convert_to((v->'source_set')::text,'UTF8'))from cr_fx where k='preview'),'Byte budget is final canonical size including its own counter');
select throws_ok($$select preview_clinical_recap(auth.uid(),pg_temp.cr_id('other_pet'),(select v from cr_fx where k='selection'))$$,'PT409',null,'Wrong-patient selection denied');
select throws_ok($$select preview_clinical_recap(auth.uid(),pg_temp.cr_id('pet'),(select jsonb_set(v,'{encounter_ids}',jsonb_build_array(pg_temp.cr_id('draft')))from cr_fx where k='selection'))$$,'PT409',null,'Unsigned selection denied');
select is(read_clinical_recap_policy(auth.uid())#>>'{policy,status}','draft','Recap policy remains independently draft');
insert into cr_fx(k,v)select'request',jsonb_build_object('pet_id',pg_temp.cr_id('pet'),'expected_pet_version',1,'policy_version',1,'selection',(select v from cr_fx where k='selection'),'expected_source_fingerprint',(select v->>'source_fingerprint'from cr_fx where k='preview'),'source_note','Fictional records only','attest_authorized',true,'previous_job_id',null);
select throws_ok($$select reserve_clinical_recap(auth.uid(),pg_temp.cr_id('job'),(select v from cr_fx where k='request'))$$,'PT403',null,'Draft policy blocks reservation but permits preview');
select save_clinical_recap_policy(auth.uid(),pg_temp.cr_id('policyaction'),'{"expected_version":1,"status":"approved","consent_text":"Synthetic LOCAL TEST ONLY","retention_text":"Synthetic retention","attest_reviewed":true}');
select is(recover_clinical_recap_policy(auth.uid(),pg_temp.cr_id('policyaction'))#>>'{policy,version}','2','Policy receipt recovers exact immutable version');
select is(cancel_clinical_recap_policy(auth.uid(),pg_temp.cr_id('policyaction'))->>'cancelled','false','Committed policy action cannot be canceled');
select is(cancel_clinical_recap_policy(auth.uid(),pg_temp.cr_id('policycancel'))->>'cancelled','true','Uncommitted policy action canceled by ID');
select throws_ok($$select save_clinical_recap_policy(auth.uid(),pg_temp.cr_id('policycancel'),'{"expected_version":2,"status":"draft","consent_text":"Late","retention_text":"Late","attest_reviewed":false}')$$,'PT409',null,'Late canceled policy write blocked');
update cr_fx set v=v||'{"policy_version":2}'where k='request';
insert into cr_fx(k,v)select'reserved',reserve_clinical_recap(auth.uid(),pg_temp.cr_id('job'),(select v from cr_fx where k='request'));
select is((select v#>>'{current,source_status}'from cr_fx where k='reserved'),'current','Reserve returns full current JobRead');
select is(reserve_clinical_recap(auth.uid(),pg_temp.cr_id('job'),(select v from cr_fx where k='request')),(select v from cr_fx where k='reserved'),'Exact reserved response recovered without another job');
select throws_ok($$select reserve_clinical_recap(auth.uid(),pg_temp.cr_id('job'),(select v||'{"source_note":"Changed"}'from cr_fx where k='request'))$$,'PT409',null,'Reserved intent cannot change');
select is(cancel_clinical_recap_reservation(auth.uid(),pg_temp.cr_id('canceled'))->>'cancelled','true','Missing reservation canceled durably');
select throws_ok($$select reserve_clinical_recap(auth.uid(),pg_temp.cr_id('canceled'),(select v from cr_fx where k='request'))$$,'PT409',null,'Late canceled reservation blocked');
select is(cancel_clinical_recap_attempt(auth.uid(),pg_temp.cr_id('attemptcancel'),pg_temp.cr_id('job'))->>'cancelled','true','Preclaim rejection has a durable exit');
select throws_ok($$select claim_clinical_recap(auth.uid(),pg_temp.cr_id('attemptcancel'),pg_temp.cr_id('job'))$$,'PT409',null,'Cancellation blocks delayed claim');
select claim_clinical_recap(auth.uid(),pg_temp.cr_id('attempt'),pg_temp.cr_id('job'));
reset role;set local role service_role;
select is(dispatch_clinical_recap(pg_temp.cr_id('attempt')),true,'One-shot dispatch admitted');select is(dispatch_clinical_recap(pg_temp.cr_id('attempt')),false,'Duplicate dispatch cannot send twice');
reset role;set local role authenticated;
select is(cancel_clinical_recap_attempt(auth.uid(),pg_temp.cr_id('attempt'),pg_temp.cr_id('job'))->>'cancelled','false','Sending work cannot be declared unsent');
insert into cr_fx(k,v)select'payload',jsonb_build_object('claims',jsonb_build_array(jsonb_build_object('claim_id','claim_001','category','history','temporal_status','historical','text','Fictional cough was documented.','uncertainty','','citations',jsonb_build_array(jsonb_build_object('source_ref',(select x->>'ref'from jsonb_array_elements(v#>'{manifest,source_set,sources}')x where x->>'kind'='signed_encounter'),'field_path','fields.subjective','quote','Fictional cough.')))),'review_flags','[]'::jsonb)from cr_fx where k='reserved';
insert into cr_fx(k,v)select'result',jsonb_build_object('request_id','synthetic-request','response_id','synthetic-response','provider_model','synthetic-model','contract_version','clinical-recap-v1','prompt_version','lrv-recap-claims-v1','manifest_sha256',(select v#>>'{manifest,sha256}'from cr_fx where k='reserved'),'language_context',jsonb_build_object('version','lrv-vet-en-v1','bundle_sha256',repeat('a',64),'request_sha256',repeat('b',64)),'payload',(select v from cr_fx where k='payload'));
reset role;set local role service_role;
select throws_ok($$select finish_clinical_recap(pg_temp.cr_id('attempt'),(select jsonb_set(v,'{payload,claims,0,citations,0,quote}','"Invented evidence"')from cr_fx where k='result'))$$,'PT422',null,'Nonliteral citation rejected');
select throws_ok($$select finish_clinical_recap(pg_temp.cr_id('attempt'),(select jsonb_set(v,'{payload,claims,0,citations,0,field_path}','"metadata.signed_by"')from cr_fx where k='result'))$$,'PT422',null,'Metadata is not a quoteable clinical field');
select is(finish_clinical_recap(pg_temp.cr_id('attempt'),(select v from cr_fx where k='result'))->>'retained','true','Received output retained separately from chart');
select is(finish_clinical_recap(pg_temp.cr_id('attempt'),(select v from cr_fx where k='result'))->>'retained','true','Lost result acknowledgement recovers exact receipt');
select throws_ok($$select finish_clinical_recap(pg_temp.cr_id('attempt'),(select v||'{"request_id":"Changed"}'from cr_fx where k='result'))$$,'PT409',null,'Different completed result rejected');
reset role;set local role authenticated;
insert into cr_fx(k,v)select'outputread',read_clinical_recap_job(auth.uid(),pg_temp.cr_id('job'));
select is((select v#>>'{job,output_id}'from cr_fx where k='outputread'),pg_temp.cr_id('attempt')::text,'Job pins the one completed output');

-- New prompt receipts coexist with retained v1 history; future/absent versions fail closed.
insert into cr_fx(k,v)select 'v2reserved',reserve_clinical_recap(auth.uid(),pg_temp.cr_id('v2job'),(select v from cr_fx where k='request'));
select claim_clinical_recap(auth.uid(),pg_temp.cr_id('v2attempt'),pg_temp.cr_id('v2job'));
reset role;set local role service_role;
select is(dispatch_clinical_recap(pg_temp.cr_id('v2attempt')),true,'V2 test attempt dispatches once');
insert into cr_fx(k,v)select 'v2result',v||jsonb_build_object('prompt_version','lrv-recap-claims-v2','manifest_sha256',(select v#>>'{manifest,sha256}'from cr_fx where k='v2reserved'))from cr_fx where k='result';
select throws_ok($$select finish_clinical_recap(pg_temp.cr_id('v2attempt'),(select v||'{"prompt_version":"lrv-recap-claims-v999"}'from cr_fx where k='v2result'))$$,'PT422',null,'Unknown prompt version cannot be retained');
select throws_ok($$select finish_clinical_recap(pg_temp.cr_id('v2attempt'),(select v||'{"prompt_version":null}'from cr_fx where k='v2result'))$$,'PT422',null,'Null prompt version cannot be retained');
select is(finish_clinical_recap(pg_temp.cr_id('v2attempt'),(select v from cr_fx where k='v2result'))->>'retained','true','V2 output retained with unchanged source contract');
select is(finish_clinical_recap(pg_temp.cr_id('v2attempt'),(select v from cr_fx where k='v2result'))->>'retained','true','V2 exact result replay is idempotent');
reset role;set local role authenticated;
select is(read_clinical_recap_job(auth.uid(),pg_temp.cr_id('v2job'))#>>'{output,provider_manifest,prompt_version}','lrv-recap-claims-v2','New output keeps v2 provenance');
select is(read_clinical_recap_job(auth.uid(),pg_temp.cr_id('job'))#>>'{output,provider_manifest,prompt_version}','lrv-recap-claims-v1','Existing v1 output remains readable and unchanged');

insert into cr_fx(k,v)select 'v3reserved',reserve_clinical_recap(auth.uid(),pg_temp.cr_id('v3job'),(select v from cr_fx where k='request'));
select claim_clinical_recap(auth.uid(),pg_temp.cr_id('v3attempt'),pg_temp.cr_id('v3job'));
reset role;set local role service_role;
select is(dispatch_clinical_recap(pg_temp.cr_id('v3attempt')),true,'V3 test attempt dispatches once');
insert into cr_fx(k,v)select 'v3result',v||jsonb_build_object('prompt_version','lrv-recap-claims-v3','manifest_sha256',(select v#>>'{manifest,sha256}'from cr_fx where k='v3reserved'))from cr_fx where k='result';
select is(finish_clinical_recap(pg_temp.cr_id('v3attempt'),(select v from cr_fx where k='v3result'))->>'retained','true','V3 classification prompt output retained');
reset role;set local role authenticated;
select is(read_clinical_recap_job(auth.uid(),pg_temp.cr_id('v3job'))#>>'{output,provider_manifest,prompt_version}','lrv-recap-claims-v3','V3 provenance remains distinct from v1/v2');


select is((select subjective from clinical_encounters where id=pg_temp.cr_id('enc')),'Fictional cough.','Recap generation does not change signed source');
reset role;
select is((select count(*)::integer from clinical_dictation_proposals where pet_id=pg_temp.cr_id('pet')),0,'Recap does not create a SOAP proposal');
set local role authenticated;
select is(read_clinical_recap_citation(auth.uid(),pg_temp.cr_id('job'),(select v#>>'{payload,claims,0,citations,0,source_ref}'from cr_fx where k='result'))#>>'{source,fields,subjective}','Fictional cough.','Citation opens frozen captured text');
insert into cr_fx(k,v)select'reviewrequest',jsonb_build_object('job_id',pg_temp.cr_id('job'),'output_id',pg_temp.cr_id('attempt'),'expected_output_hash',v#>>'{output,payload_sha256}','expected_review_version',1,'manifest_sha256',v#>>'{manifest,sha256}','decision','accepted','accepted_claims',jsonb_build_array(jsonb_build_object('claim_id','claim_001','text','Reviewed historical cough.')),'review_note','','attest_reviewed',true)from cr_fx where k='outputread';
select is(save_clinical_recap_review(auth.uid(),pg_temp.cr_id('review'),(select v from cr_fx where k='reviewrequest'))#>>'{review,accepted_claims,0,proposed_text}','Fictional cough was documented.','Reviewed item keeps original model wording');
select is(recover_clinical_recap_review(auth.uid(),pg_temp.cr_id('review'),pg_temp.cr_id('job'))#>>'{review,accepted_claims,0,reviewed_text}','Reviewed historical cough.','Review receipt recovers distinct reviewer wording');
select is(cancel_clinical_recap_review(auth.uid(),pg_temp.cr_id('review'),pg_temp.cr_id('job'))->>'cancelled','false','Committed review cannot be canceled');
select throws_ok($$select save_clinical_recap_review(auth.uid(),gen_random_uuid(),(select v from cr_fx where k='reviewrequest'))$$,'PT409',null,'Competing second review rejected');
select add_clinical_addendum(pg_temp.cr_id('enc'),'Later addendum not in original capture.');
select is(read_clinical_recap_job(auth.uid(),pg_temp.cr_id('job'))#>>'{current,source_status}','stale','Addendum append stales prior manifest despite immutable encounter');
select is(read_clinical_recap_job(auth.uid(),pg_temp.cr_id('job'))#>>'{current,reasons,0}','addenda_changed','Append gets precise canonical stale reason');
-- Imported-link eligibility changes without a problem UPDATE; epoch derives actual problem patient.
reset role;
insert into cr_fx(k,v)select'epoch_before',to_jsonb(version)from clinical_recap_epochs where pet_id=pg_temp.cr_id('pet');
insert into ezyvet_history_requests(id,actor_id,pet_id,kind,status,payload,request_hash,review_context)values(pg_temp.cr_id('link'),pg_temp.cr_id('actor'),pg_temp.cr_id('pet'),'problem_extraction','prepared','{}',repeat('c',64),'{}');
insert into ezyvet_problem_extractions(id,pet_id,problem_id,action,problem_version,problem_fields,extracted_by)values(pg_temp.cr_id('link'),pg_temp.cr_id('other_pet'),pg_temp.cr_id('problem'),'link',1,'{}',pg_temp.cr_id('actor'));
select is((select version from clinical_recap_epochs where pet_id=pg_temp.cr_id('pet')),(select(v#>>'{}')::bigint+1 from cr_fx where k='epoch_before'),'Extraction epoch follows actual problem patient, not mismatched row pet');
set local role authenticated;
select is(preview_clinical_recap(auth.uid(),pg_temp.cr_id('pet'),(select v from cr_fx where k='selection'))#>>'{source_set,budgets,problems}','0','Outside-linked native problem excluded even unchanged');
insert into cr_fx(k,v)select'withoutproblems',preview_clinical_recap(auth.uid(),pg_temp.cr_id('pet'),(select v||'{"include_native_problems":false}'from cr_fx where k='selection'));
select is((select v#>>'{source_set,exclusions,outside_linked_problem_count}'from cr_fx where k='withoutproblems'),null,'Omitted problem family has fixed null exclusion count');
select save_patient_problem(pg_temp.cr_id('problem'),pg_temp.cr_id('pet'),1,'Locally edited outside problem','Edited',null,'active','routine');
select is(preview_clinical_recap(auth.uid(),pg_temp.cr_id('pet'),(select v||'{"include_native_problems":false}'from cr_fx where k='selection'))->>'source_fingerprint',(select v->>'source_fingerprint'from cr_fx where k='withoutproblems'),'Omitted problem edit does not stale selected source fingerprint');
-- Policy action recovery survives ADMIN demotion without permitting new writes.
reset role;delete from user_roles where user_id=pg_temp.cr_id('actor')and role='ADMIN';insert into user_roles(user_id,role)values(pg_temp.cr_id('actor'),'STAFF')on conflict do nothing;set local role authenticated;
select is(recover_clinical_recap_policy(auth.uid(),pg_temp.cr_id('policyaction'))#>>'{policy,version}','2','Demoted active staff can recover owned policy receipt');
select is(cancel_clinical_recap_policy(auth.uid(),gen_random_uuid())->>'cancelled','true','Demoted active staff can cancel missing owned action');
select throws_ok($$select save_clinical_recap_policy(auth.uid(),gen_random_uuid(),'{"expected_version":2,"status":"draft","consent_text":"Unauthorized","retention_text":"Unauthorized","attest_reviewed":false}')$$,'PT403',null,'Demotion prevents a new policy write');
reset role;
select throws_ok($$update clinical_recap_manifests set document='{}'where id=pg_temp.cr_id('job')$$,'23514',null,'Frozen manifest cannot be rewritten');
select *from finish();rollback;
